for(const route of levelRoutes)route.forEach((cell,index)=>{cell.id=`world-${levelRoutes.indexOf(route)+1}-cell-${index}`;cell.index=index;cell.label=cell.name;cell.action=cell.type});
const routeCells=(level=game.level)=>levelRoutes[level]||[];

const defaultGame=()=>({level:0,position:0,energy:0,deckQueues:{},keys:[false,false,false,false,false],laps:[0,0,0,0,0],request:'',originalRequest:'',requestHistory:[],requestReviews:[],pendingOcean:null,stage:'request',lapEnergyEvents:[],circleProgress:null,pendingMovement:null,pendingRoll:null,pendingEffects:null,pendingCardCompletion:null,visitedCells:{},skipTurns:0,bodyMarks:[],acceptedCards:[],finalInsight:'',trueNeed:'',choice:'',acceptanceInsight:'',acceptedPower:'',guardianInsight:'',mainShadow:'',insights:[],openedCards:[],turn:0,lastRoll:null,pendingReflection:null,returnGuardianInsight:'',lifeGoals:[],energyHistory:[],creationActions:[]});
function loadGame(){try{const raw=JSON.parse(localStorage.getItem(GAME_STORAGE_KEY));if(!raw||!Number.isInteger(raw.position)||raw.position<0||(raw.level<=4&&raw.position>=levelRoutes[raw.level].length)||!Number.isInteger(raw.level)||raw.level<0||raw.level>4)return defaultGame();const base=defaultGame();return {...base,...raw,energy:Math.max(0,Number(raw.energy)||0),keys:Array.isArray(raw.keys)?raw.keys.slice(0,5).map(Boolean):base.keys,laps:Array.isArray(raw.laps)?raw.laps.slice(0,5):base.laps,insights:Array.isArray(raw.insights)?raw.insights:[],openedCards:Array.isArray(raw.openedCards)?raw.openedCards:[],bodyMarks:Array.isArray(raw.bodyMarks)?raw.bodyMarks:[],lifeGoals:Array.isArray(raw.lifeGoals)?raw.lifeGoals:[],energyHistory:Array.isArray(raw.energyHistory)?raw.energyHistory:[],creationActions:Array.isArray(raw.creationActions)?raw.creationActions:[],acceptedCards:Array.isArray(raw.acceptedCards)?raw.acceptedCards:[],originalRequest:String(raw.originalRequest||raw.request||'').trim(),finalInsight:raw.finalInsight||'',trueNeed:raw.trueNeed||'',choice:raw.choice||'',acceptanceInsight:raw.acceptanceInsight||'',acceptedPower:raw.acceptedPower||'',guardianInsight:raw.guardianInsight||'',mainShadow:raw.mainShadow||'',stage:String(raw.originalRequest||raw.request||'').trim()?(raw.stage||'intro'):'request',skipTurns:Number(raw.skipTurns)||0,deckQueues:raw.deckQueues&&typeof raw.deckQueues==='object'?raw.deckQueues:{}}}catch{return defaultGame()}}
let game=loadGame(),cardManifest={},shadowDescriptions={},moving=false,pendingPortal=false,modalOpen=false,toastTimer,activeCard=null,boardLevelRendered=-1;
let soundEnabled=localStorage.getItem('tochka-sily-sound')!=='off',audioContext;
function playSound(kind){globalThis.SoundManager?.play(kind==='key'?'keyReveal':kind==='card'?'cardDraw':kind)}

const ge=id=>document.getElementById(id);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(GAME_STORAGE_KEY,JSON.stringify(game))}catch{announce('Прогресс не удалось сохранить в этом браузере.')}}
function announce(message){let toast=ge('game-toast');if(!toast){toast=document.createElement('div');toast.id='game-toast';toast.className='toast';toast.setAttribute('role','status');document.body.append(toast)}toast.textContent=message;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,2600)}
function renderGame(){const route=routeCells(),c=route[game.position],playing=game.level<=4,hasRequest=!!game.originalRequest.trim(),ready=hasRequest&&game.stage==='board';if(boardLevelRendered!==game.level&&playing)makeBoard();ge('request-gate').hidden=hasRequest&&game.stage!=='request';ge('level-intro').hidden=!hasRequest||game.stage!=='intro';ge('level2-intro').hidden=!hasRequest||game.stage!=='intro2';ge('level3-intro').hidden=!hasRequest||game.stage!=='intro3';ge('level5-intro').hidden=!hasRequest||game.stage!=='intro5';ge('center-stage').hidden=game.stage!=='center';ge('spheres-button').hidden=game.level!==4;ge('game-play-content').hidden=!ready;ge('play-status').innerHTML=`<span class="status-pill">Уровень: <b>${escapeHtml(levels[game.level].name)}</b></span><span class="status-pill">Энергия: <b>⚡ ${game.energy}</b></span>${game.level===4?`<span class="status-pill">Направлено: <b>⚡ ${directedEnergy()}</b></span>`:''}<span class="status-pill key-status">Ключ: <b class="${game.keys[game.level]?'key-owned':'key-empty'}">⚿ ${game.keys[game.level]?'получен':'не получен'}</b></span><span class="status-pill">Круг: <b>${game.laps[game.level]+1}</b></span>`;
  document.querySelector('.play-layout').hidden=!playing;ge('future-level').hidden=playing;ge('roll-button').disabled=!playing||!ready||moving||modalOpen;ge('play-level-name').textContent=`Уровень ${game.level+1} · ${levels[game.level].name}`;ge('board-image').alt=`Игровое поле уровня ${game.level+1}`;ge('board-center-label').hidden=game.level!==1;ge('board-note').textContent=game.level===4?'Пятый уровень: 20 игровых клеток и Портал в Центр. Направляйте энергию в выбранные цели.':game.level===3?'Четвертый уровень: 20 игровых клеток и Портал. Возвращайте энергию и накопите 25 ⚡ для перехода.':game.level===2?'Третий уровень: 20 игровых клеток и Портал. Фишка движется строго по видимому кругу.':game.level===1?'Второй уровень: 20 игровых клеток и Портал.':'Первый уровень: 19 игровых клеток и Портал.';ge('awareness-button').textContent=game.level===4?'Моя карта творения':game.level===3?'Моя карта возвращения':game.level===2?'Моя карта принятия':game.level===1?'Моя карта потребностей':'Моя карта осознания';
  if(!playing){ge('future-title').textContent=levels[game.level].name;return}
  ge('player-token').style.left=c.x+'%';ge('player-token').style.top=c.y+'%';ge('current-cell-name').textContent=c.name;ge('current-cell-description').textContent=c.description||cellDescription(c.type);ge('turn-message').textContent=game.lastRoll?`Последний бросок: ${game.lastRoll}. ${c.name}.`:'Фишка стоит у входного Портала.';
  const scroller=document.querySelector('.board-scroll'),board=ge('board');if(scroller.scrollWidth>scroller.clientWidth)scroller.scrollLeft=Math.max(0,board.clientWidth*c.x/100-scroller.clientWidth/2);
  document.querySelectorAll('.cell-hit').forEach(b=>b.classList.toggle('active',Number(b.dataset.position)===game.position));
}
function cellDescription(type){return {need:'Вытяните карту «Потребности».',shadow:'Вытяните карту «Тень ↔ Сила».',return:'Вытяните карту «Возвращение энергии».',creation:'Вытяните карту «Творение».',action:'Запишите конкретное действие.',goal:'Выберите сферу, цель и энергию.',creationInsight:'Запишите, чего хотите на самом деле.',returnInsight:'Запишите осознание о возвращении энергии.',support:'Вытяните карту поддержки.',acceptance:'Запишите, какую Силу вы принимаете.',trueNeed:'Сформулируйте свою истинную потребность.',event:'Вытяните карту «Особое событие».',energy:'Получите 1 ⚡.',archetype:'Открой карту «Богини / Архетипы силы» и найди качество для своего запроса.',diagnostic:'Вытяните карту «Диагностика».',ocean:'Уточните свой запрос.',insight:'Запишите осознание в журнал.',key:'Получите ключ этого уровня.',guardian:'Сформулируйте главное осознание.',view:'Вытяните карту «Другой взгляд».'}[type]||''}
function makeBoard(){const route=routeCells();boardLevelRendered=game.level;ge('board-cells').innerHTML=route.map(c=>`<button type="button" class="cell-hit ${c.large?'large':''}" data-position="${c.index}" style="left:${c.x}%;top:${c.y}%" aria-label="${c.index===0?'Портал':c.name}: ${escapeHtml(c.label)}" title="${escapeHtml(c.label)}"></button>`).join('')}
ge('board-cells').addEventListener('click',e=>{const button=e.target.closest('.cell-hit');if(!button||!game.originalRequest.trim()||game.stage!=='board')return;const c=routeCells()[Number(button.dataset.position)];if(!c)return;ge('current-cell-name').textContent=c.name;ge('current-cell-description').textContent=c.description||cellDescription(c.type)});
function showModal(kicker,title,html,buttons){modalOpen=true;ge('game-modal').hidden=false;ge('modal-kicker').textContent=kicker;ge('modal-title').textContent=title;ge('modal-content').innerHTML=html;const row=ge('modal-buttons');row.replaceChildren();for(const b of buttons){const btn=document.createElement('button');btn.type='button';btn.textContent=b.label;if(b.secondary)btn.className='secondary';btn.addEventListener('click',b.action);row.append(btn)}renderGame();ge('modal-close').focus({preventScroll:true});ge('game-modal').querySelector('.modal-card').scrollTop=0}
function closeModal(){if(game.pendingOcean){announce('Оставь запрос или сохрани новую формулировку.');return}if(typeof pendingLapEnergy==='function'&&pendingLapEnergy()){announce('Выбери: принять энергию или отказаться.');return}if(game.pendingReflection){announce('Сначала запишите осознание по выпавшей карте.');return}ge('game-modal').hidden=true;modalOpen=false;renderGame();if(pendingPortal){pendingPortal=false;showPortalChoice()}}
ge('modal-close').addEventListener('click',closeModal);
ge('game-modal').addEventListener('click',e=>{if(e.target===ge('game-modal'))closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalOpen)closeModal()});
function singleClose(label='Вернуться к полю'){return [{label,action:closeModal}]}
function currentRequest(){return String(game.request||game.originalRequest||'').trim()}
function saveInsight(kind,value){const text=value.trim();if(!text){announce('Запишите осознание перед сохранением.');return false}game.insights.push({kind,requestAtTime:currentRequest(),level:game.level,cell:game.position,text,at:new Date().toISOString()});persist();return true}
function shuffledIds(pool){const ids=pool.map(c=>c.id);for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}return ids}
function cardFor(deck){const pool=(cardManifest[deck]||[]).filter(c=>deck!=='Особое событие'||c.availableLevels?.includes(game.level+1));if(!Array.isArray(pool)||!pool.length){showModal('Колода ожидает загрузки',deck,'<p>Карты этой колоды еще не подключены.</p>',singleClose());return}let queue=game.deckQueues[deck];if(!Array.isArray(queue)||!queue.length){queue=shuffledIds(pool);if(pool.length>1&&queue[0]===game.lastCardId?.[deck])queue.push(queue.shift())}let card=pool.find(c=>c.id===queue[0]);if(!card){queue=shuffledIds(pool);card=pool.find(c=>c.id===queue[0])}if(deck==='Тень ↔ Сила'&&!shadowDescriptions[card.id]){showModal('Описание недоступно','Попробуйте еще раз','<p>Не удалось загрузить описание этой пары из книги. Карта не засчитана.</p>',singleClose());return}game.deckQueues[deck]=queue.slice(1);game.lastCardId||={};game.lastCardId[deck]=card.id;const eventId=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`;game.openedCards.push({deck,id:card.id,eventId,requestAtTime:currentRequest(),level:game.level,cell:game.position,snapshot:typeof snapshotCard==='function'?snapshotCard(card):null,at:new Date().toISOString(),accepted:false});activeCard=card;persist();showDrawnCard(card)}
function showDrawnCard(card){activeCard=card;playSound('card');const archetype=card.deck==='Богини / Архетипы силы';const image=card.image?`<img class="card-image" src="${escapeHtml(card.image)}" alt="Образ архетипа: ${escapeHtml(card.title)}">`:'';const names={'Главная грань':'Качества','Ресурс':'Что дает','Особенно нужен, когда':'Когда нужна','Ключ':'Ключевая фраза'};const fields=(card.fields||[]).filter(f=>!archetype||f.label!=='Архетип'||f.text!==card.title).map(field=>`<div class="card-field"><strong>${escapeHtml(archetype?(names[field.label]||field.label):field.label)}</strong><p>${escapeHtml(field.text)}</p></div>`).join('');const details=`<article class="drawn-card">${archetype?'':`<span class="drawn-deck">${escapeHtml(card.deck)}</span>`}<h3>${escapeHtml(card.title)}</h3>${fields}</article>`;const content=archetype?`<div class="archetype-page">${image}${details}</div>`:image+details;let buttons=[{label:'Принять эту карту',action:()=>acceptCard(card)}];if(card.deck==='Диагностика'||card.deck==='Другой взгляд'||card.deck==='Потребности'||card.deck==='Тень ↔ Сила'||card.deck==='Богини / Архетипы силы')buttons.push({label:'Выбрать другую карту',secondary:true,action:()=>cardFor(card.deck)});if(card.deck==='Творение'&&[1,3,9,10,11,12,13].includes(card.number))buttons.push({label:'Принять и открыть «Сферы жизни»',secondary:true,action:async()=>{await acceptCard(card);showSphereTablet()}});showModal(archetype?'':'Карта',card.title,content,buttons);ge('modal-content').querySelector('.card-image')?.addEventListener('error',e=>{e.currentTarget.remove();announce('Изображение не загрузилось. Текст карты доступен.')},{once:true})}
async function moveSteps(steps,resuming=false){const route=routeCells();if(!route.length)return;if(game.pendingMovement&&!resuming)return;moving=true;game.circleProgress||=Array(5).fill(null);if(!Number.isFinite(game.circleProgress[game.level]))game.circleProgress[game.level]=game.position;if(!resuming)game.pendingMovement={id:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,level:game.level,direction:Math.sign(steps),remaining:Math.abs(steps)};persist();renderGame();const movement=game.pendingMovement;while(movement.remaining>0){game.position=(game.position+movement.direction+route.length)%route.length;movement.remaining--;game.circleProgress[game.level]+=movement.direction;game.visitedCells||={};game.visitedCells[route[game.position].id]=true;if(movement.direction>0&&game.position===0&&game.circleProgress[game.level]>=route.length){game.circleProgress[game.level]-=route.length;game.laps[game.level]++;game.portalReached=true;game.portalDeferred=false;if(game.level>=3||canPassPortal())pendingPortal=true;if(typeof offerLapEnergy==='function'){const event=createLapEnergyEvent(game.level,game.laps[game.level]);persist();renderGame();await offerLapEnergy(event)}else if(typeof awardLapCrystal==='function')awardLapCrystal(game.level,game.laps[game.level]);}persist();renderGame();playSound('boardStep');await delay(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?0:300)}game.pendingMovement=null;moving=false;persist();renderGame()}
async function applyEffects(card){const effects=card.effects||[];if(!game.pendingEffects){const cost=effects.filter(e=>e.type==='energy'&&e.amount<0).reduce((n,e)=>n-e.amount,0);if(game.energy<cost)return 'Недостаточно энергии для действия карты. Баланс и позиция не изменены.';game.pendingEffects={cardId:card.id,index:0,notes:[]};persist()}const state=game.pendingEffects;for(let i=state.index;i<effects.length;i++){const effect=effects[i];state.index=i+1;if(effect.type==='energy'){if(effect.amount>0)earnEnergy(effect.amount,'Особое событие');else game.energy=Math.max(0,game.energy+effect.amount);state.notes.push(`⚡ ${effect.amount>0?'+':''}${effect.amount}`)}else if(effect.type==='move'){persist();await moveSteps(effect.steps);state.notes.push(`Фишка переместилась на ${Math.abs(effect.steps)} клеток ${effect.steps>0?'вперед':'назад'}.`)}else if(effect.type==='skipTurn'){game.skipTurns+=effect.count;state.notes.push('Следующий ход пропускается.')}else if(effect.type==='support'){const destination=routeCells().findIndex(c=>c.type==='support');persist();if(destination>=0){await moveSteps((destination-game.position+routeCells().length)%routeCells().length);state.notes.push('Вы получили поддержку Архетипа.')}}persist()}const note=state.notes.join(' · ');game.pendingEffects=null;persist();renderGame();return note}
async function acceptCard(card,resuming=false){const opened=game.openedCards.at(-1);if(!opened||opened.id!==card.id||(opened.accepted&&!resuming))return;if(card.deck==='Тень ↔ Сила'&&!shadowDescriptions[card.id]){announce('Описание карты пока не загрузилось.');return}if(!resuming){opened.accepted=true;game.acceptedCards.push({deck:card.deck,id:card.id,title:card.title,level:game.level,eventId:opened.eventId,at:new Date().toISOString()});if(card.deck==='Тень ↔ Сила')game.pendingReflection={cardId:card.id,eventId:opened.eventId};game.pendingCardCompletion={deck:card.deck,id:card.id};persist()}const note=await applyEffects(card);game.pendingCardCompletion=null;persist();if(card.effects?.some(e=>e.type==='support')){cardFor('Богини / Архетипы силы');return}if(card.deck==='Тень ↔ Сила'){showShadowReflection(card);return}if(card.deck==='Богини / Архетипы силы'){showModal('Поддержка',card.title,'<p>Поддержка Архетипа сохранена в вашем игровом пути.</p>',singleClose('Продолжить'));return}if(card.deck==='Диагностика'||card.deck==='Потребности'){showModal(card.deck,'Отметить отклик',`<p>Карта «${escapeHtml(card.title)}» принята. ${card.deck==='Потребности'?'Где в теле вы чувствуете эту потребность?':'Где в теле вы чувствуете отклик на эту тему?'}</p>${note?`<p>${escapeHtml(note)}</p>`:''}`,[{label:'Отметить на Карте тела',action:()=>showBodyMap(card)},{label:'Продолжить игру',secondary:true,action:closeModal}])}else if(note)showModal('Карта принята',card.title,`<p>${escapeHtml(note)}</p><p class="modal-note">После перемещения картой конечная клетка пока не активируется: это правило ожидает уточнения.</p>`,singleClose('Продолжить'));else closeModal()}

function showKey(){playSound('key');showModal(game.level===4?'Ключ Воплощения':game.level===3?'Ключ Энергии':game.level===2?'Ключ Принятия':game.level===1?'Ключ Потребности':'Ключ Ясности','Ключ получен','<div class="key-reveal" aria-label="Золотой ключ"><span>⚿</span></div><p>Ключ сохранен. После завершения круга вы сможете выбрать переход у Портала.</p>',singleClose())}

function showShortReflection(kind,title,question,previous=''){showModal(`Уровень ${game.level+1}`,title,`<p>${escapeHtml(question)}</p><label for="modal-text">Мое осознание</label><textarea id="modal-text">${escapeHtml(previous)}</textarea>`,[{label:'Сохранить в журнал',action:()=>{const value=ge('modal-text').value;if(!hasReflectionText(value)){announce('Запишите хотя бы два непробельных символа.');return}if(saveInsight(kind,value)){if(kind==='Хранитель истины')game.returnGuardianInsight=value.trim();if(kind==='Хранитель будущего')game.futureGuardianInsight=value.trim();persist();closeModal()}}},{label:'Позже',secondary:true,action:closeModal}]);const field=ge('modal-text'),button=ge('modal-buttons').querySelector('button');field.addEventListener('input',()=>button.disabled=!hasReflectionText(field.value));button.disabled=!hasReflectionText(field.value)}
function showReturnMap(){showModal('Итог уровня','Моя карта возвращения',`<div class="awareness"><h3>Мой запрос</h3><p>${escapeHtml(currentRequest())}</p><h3>Возвращение энергии</h3>${game.acceptedCards.filter(c=>c.level===3&&c.deck==='Возвращение энергии').map(c=>`<p>${escapeHtml(c.title)}</p>`).join('')||'<p>Карты пока не исследованы.</p>'}<h3>Мои осознания</h3>${game.insights.filter(i=>i.level===3).map(i=>`<p>${escapeHtml(i.text)}</p>`).join('')||'<p>Записи пока нет.</p>'}<h3>Энергия и ключ</h3><p>⚡ ${game.energy} / 25 · Круги: ${game.laps[3]}</p><p class="${game.keys[3]?'key-owned':'key-empty'}">⚿ ${game.keys[3]?'Ключ Энергии получен':'Ключ пока не получен'}</p></div>`,singleClose())}
function pulseEnergy(){const pill=ge('play-status').querySelectorAll('.status-pill')[1];pill.classList.remove('energy-pop');void pill.offsetWidth;pill.classList.add('energy-pop');setTimeout(()=>pill.classList.remove('energy-pop'),850)}
const directedEnergy=()=>game.lifeGoals.reduce((sum,goal)=>sum+goal.amount,0);
const sphereName=id=>lifeSpheres.find(s=>s.id===id)?.name||id;
function showSphereTablet(){const amounts=lifeSpheres.map(s=>game.lifeGoals.filter(g=>g.sphereId===s.id).reduce((sum,g)=>sum+g.amount,0));const max=Math.max(1,...amounts);const span=360/lifeSpheres.length;const colors=amounts.map((n,i)=>{const a=(.09+.72*n/max).toFixed(2),start=(i*span+1).toFixed(2),end=((i+1)*span-1).toFixed(2);return `rgba(246,190,91,${a}) ${start}deg ${end}deg, transparent ${end}deg ${((i+1)*span).toFixed(2)}deg`}).join(',');const sectors=lifeSpheres.map((s,i)=>`<button type="button" class="sphere-row" data-sphere="${s.id}"><span>${escapeHtml(s.name)}</span><strong>${amounts[i]} ⚡</strong><span class="sphere-meter"><i style="width:${Math.round(amounts[i]/max*100)}%"></i></span></button>`).join('');const goals=game.lifeGoals.map(g=>`<div class="sphere-goal"><strong>${escapeHtml(sphereName(g.sphereId))}</strong><p>${escapeHtml(g.title)}</p><span>${g.amount} ⚡ направлено</span>${g.amount?`<button type="button" data-return-goal="${escapeHtml(g.id)}">Вернуть энергию</button>`:''}</div>`).join('')||'<p>Цели появятся здесь после подтверждения распределения.</p>';showModal('Уровень 5','Сферы жизни',`<div class="sphere-tablet"><p>Куда я направляю свою энергию?</p><div class="energy-wheel" style="background:conic-gradient(${colors})"><div><small>Доступная энергия</small><strong>${game.energy} ⚡</strong><small>Направлено ${directedEnergy()} ⚡</small></div></div><p class="modal-note">Общий ресурс: ${game.energy+directedEnergy()} ⚡</p><div class="sphere-list">${sectors}</div><h3>Мои цели</h3><div class="sphere-goals">${goals}</div></div>`,[{label:'Добавить цель',action:()=>showGoalEditor()},{label:'Вернуться к игре',secondary:true,action:closeModal}]);ge('modal-content').querySelectorAll('[data-sphere]').forEach(b=>b.addEventListener('click',()=>showGoalEditor({sphereId:b.dataset.sphere})));ge('modal-content').querySelectorAll('[data-return-goal]').forEach(b=>b.addEventListener('click',()=>confirmEnergyReturn(b.dataset.returnGoal)))}
function showGoalEditor(draft={}){const options=lifeSpheres.map(s=>`<option value="${s.id}" ${draft.sphereId===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('');showModal('Уровень 5','Какую цель я выбираю?',`<p>Выбери сферу, сформулируй цель и реши, сколько энергии направить в нее.</p><p class="modal-note">Доступно: ${game.energy} ⚡ · Направлено: ${directedEnergy()} ⚡</p><label for="goal-sphere">Сфера жизни</label><select id="goal-sphere"><option value="">Выбрать сферу</option>${options}</select><label for="goal-title">Моя цель</label><textarea id="goal-title" placeholder="Что я хочу создать?">${escapeHtml(draft.title||'')}</textarea><label for="goal-energy">Направляю энергии</label><input id="goal-energy" type="number" min="1" max="${game.energy}" step="1" value="${escapeHtml(draft.amount||'')}"><p class="modal-note" id="goal-feedback">Подтверждение появится до распределения энергии.</p>`,[{label:'Продолжить',action:()=>{const sphereId=ge('goal-sphere').value,title=ge('goal-title').value.trim(),amount=Number(ge('goal-energy').value);if(!lifeSpheres.some(s=>s.id===sphereId)||!hasReflectionText(title)||!Number.isSafeInteger(amount)||amount<1){ge('goal-feedback').textContent='Выбери сферу, запиши цель (минимум 2 непробельных символа) и укажи целое число энергии от 1.';return}if(amount>game.energy){ge('goal-feedback').textContent=`Доступно только ${game.energy} ⚡. Уменьши количество энергии.`;return}showGoalConfirm({sphereId,title,amount})}},{label:'Сферы жизни',secondary:true,action:showSphereTablet}])}
function showGoalConfirm(draft){let committed=false;showModal('Подтверждение','Направить энергию?',`<p>Ты направляешь <b>${draft.amount} ⚡</b> в сферу «${escapeHtml(sphereName(draft.sphereId))}» на цель «${escapeHtml(draft.title)}». Подтвердить?</p><p class="modal-note">Доступно сейчас: ${game.energy} ⚡</p>`,[{label:'Направить энергию',action:()=>{if(committed)return;if(draft.amount>game.energy){announce(`Доступно только ${game.energy} ⚡.`);showGoalEditor(draft);return}committed=true;const id=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`;const at=new Date().toISOString();game.energy-=draft.amount;game.lifeGoals.push({id,sphereId:draft.sphereId,title:draft.title,amount:draft.amount,at});game.energyHistory.push({kind:'directed',goalId:id,amount:draft.amount,sphereId:draft.sphereId,at});persist();renderGame();showSphereTablet()}},{label:'Изменить',secondary:true,action:()=>showGoalEditor(draft)}])}
function confirmEnergyReturn(id){const goal=game.lifeGoals.find(g=>g.id===id&&g.amount>0);if(!goal){showSphereTablet();return}showModal('Сферы жизни','Вернуть направленную энергию?',`<p>Вернуть ${goal.amount} ⚡ из цели «${escapeHtml(goal.title)}» в доступную энергию?</p>`,[{label:'Вернуть энергию',action:()=>{const amount=goal.amount;goal.amount=0;game.energy+=amount;game.energyHistory.push({kind:'returned',goalId:id,amount,sphereId:goal.sphereId,at:new Date().toISOString()});persist();renderGame();showSphereTablet()}},{label:'Оставить',secondary:true,action:showSphereTablet}])}
function showCreationAction(){showModal('Уровень 5','Какое действие я сделаю?','<p>Какой конкретный шаг поможет направить твою энергию в создание желаемого?</p><label for="modal-text">Мое действие</label><textarea id="modal-text"></textarea>',[{label:'Сохранить действие',action:()=>{const value=ge('modal-text').value.trim();if(!hasReflectionText(value)){announce('Запиши хотя бы два непробельных символа.');return}game.creationActions.push({text:value,cell:game.position,at:new Date().toISOString()});saveInsight('Действие',value);persist();closeModal()}},{label:'Позже',secondary:true,action:closeModal}]);const field=ge('modal-text'),button=ge('modal-buttons').querySelector('button');field.addEventListener('input',()=>button.disabled=!hasReflectionText(field.value));button.disabled=true}
function showCreationMap(){const goals=game.lifeGoals.map(g=>`<p><b>${escapeHtml(sphereName(g.sphereId))}:</b> ${escapeHtml(g.title)} · ${g.amount} ⚡</p>`).join('')||'<p>Цели пока не созданы.</p>';const actions=game.creationActions.map(a=>`<p>${escapeHtml(a.text)}</p>`).join('')||'<p>Действия пока не записаны.</p>';showModal('Итог уровня','Моя карта творения',`<div class="awareness"><h3>Мои цели</h3>${goals}<h3>Мои действия</h3>${actions}<h3>Осознания</h3>${game.insights.filter(i=>i.level===4&&i.kind!=='Действие').map(i=>`<p>${escapeHtml(i.text)}</p>`).join('')||'<p>Пока нет записей.</p>'}<h3>Энергия</h3><p>Доступно ${game.energy} ⚡ · Направлено ${directedEnergy()} ⚡ · Всего ${game.energy+directedEnergy()} ⚡</p></div>`,[{label:'Сферы жизни',action:showSphereTablet},{label:'Продолжить',secondary:true,action:closeModal}])}

function handleCell(){const c=routeCells()[game.position];switch(c.type){
  case 'portal':return;
  case 'energy':earnEnergy(1,'Энергетическая клетка');persist();renderGame();pulseEnergy();announce('+1 ⚡ Энергия получена');return;
  case 'archetype':cardFor('Богини / Архетипы силы');return;
  case 'diagnostic':cardFor('Диагностика');return;
  case 'need':cardFor('Потребности');return;
  case 'shadow':cardFor('Тень ↔ Сила');return;
  case 'return':cardFor('Возвращение энергии');return;
  case 'creation':cardFor('Творение');return;
  case 'action':showCreationAction();return;
  case 'goal':showGoalEditor();return;
  case 'creationInsight':showShortReflection('Чего я хочу на самом деле?','Чего я хочу на самом деле?','Что я теперь осознаю о том, что хочу создать в своей жизни?');return;
  case 'returnInsight':showShortReflection('Я возвращаю свою энергию','Я возвращаю свою энергию','Где сейчас находится мое внимание и что я хочу вернуть себе?');return;
  case 'support':cardFor('Богини / Архетипы силы');return;
  case 'acceptance':showAcceptance();return;
  case 'trueNeed':showTrueNeed();return;
  case 'event':cardFor('Особое событие');return;
  case 'view':cardFor('Другой взгляд');return;
  case 'key':if(game.level>=3){game.keys[game.level]=true;persist();renderGame();showKey();return}game.level===2?showLevel3Guardian('Ключ Принятия'):game.level===1?showLevel2Key():showKeyCondition();return;
  case 'ocean':showOcean();return;
  case 'insight':showModal('Клетка осознания','Запиши свое осознание','<label for="modal-text">Что ты осознала?</label><textarea id="modal-text" placeholder="Мое осознание..."></textarea>',[{label:'Сохранить в журнал',action:()=>{if(saveInsight('Осознание',ge('modal-text').value))closeModal()}},{label:'Позже',secondary:true,action:closeModal}]);return;
  case 'guardian':game.level===4?showShortReflection('Хранитель будущего','Хранитель будущего','Какое будущее я начинаю создавать и какой шаг приближает меня к нему?',game.futureGuardianInsight||''):game.level===3?showShortReflection('Хранитель истины','Хранитель истины','Что я заметила о своей энергии и что возвращаю себе?',game.returnGuardianInsight||''):game.level===2?showLevel3Guardian('Хранитель истины'):game.level===1?showChoiceGuardian():showFinalInsight('Хранитель Правды');return;
}}
function canPassPortal(level=game.level){return game.laps[level]>=1&&game.keys[level]&&(level!==0||(!!game.originalRequest.trim()&&!!game.finalInsight.trim()&&game.bodyMarks.length>0))&&(level!==1||(!!game.trueNeed.trim()&&!!game.choice.trim()&&game.bodyMarks.some(m=>m.gameLevel===1)))&&(level!==2||(game.insights.some(i=>i.level===2&&i.kind==='Тень ↔ Сила'&&i.rewardClaimed)&&!!game.guardianInsight.trim()&&!!game.acceptedPower.trim()))&&(level!==3||game.energy>=25)}
function transitionTo(nextLevel){game.level=nextLevel;game.position=0;game.stage=nextLevel===1?'intro2':nextLevel===2?'intro3':nextLevel===4?'intro5':'board';persist();closeModal();const screen=ge('transition-screen');ge('transition-title').textContent=`Уровень ${nextLevel+1}`;ge('transition-name').textContent=levels[nextLevel].name;ge('transition-path').textContent=`${levels[nextLevel-1].name} → ${levels[nextLevel].name}`;screen.hidden=false;setTimeout(()=>{screen.hidden=true;renderGame()},1200);renderGame()}
function showPortalChoice(){if(game.level===4){if(!canPassPortal()){showModal('Портал','Переход в Центр','<p>Для перехода в Центр нужен Ключ Воплощения. Продолжайте движение по кругу.</p>',singleClose('Продолжить игру'));return}showModal('Портал','Переход в Центр','<p>Пятый круг завершен. Центр игры пока ожидает отдельного сценария.</p>',[{label:'Перейти в Центр',action:()=>{game.stage='center';game.position=0;persist();closeModal()}},{label:'Остаться на пятом уровне',secondary:true,action:closeModal}]);return}const next=levels[game.level+1];if(!next)return;if(game.level===3){if(game.energy<25){showModal('Портал','Продолжить возвращать энергию',`<p>Для перехода на уровень «Я создаю» необходимо накопить 25 ⚡ энергии.</p><p>Сейчас: ${game.energy} ⚡ / 25 ⚡</p>`,singleClose('Продолжить игру'));return}if(!game.keys[3]){showModal('Портал','Нужен Ключ Энергии','<p>Получите Ключ на клетке №6 и продолжайте путь по кругу.</p>',singleClose('Продолжить игру'));return}showModal('Портал','Переход на уровень 5','<p>Ты накопил достаточно энергии для перехода на уровень «Я создаю». Ты готов перейти?</p>',[{label:'Перейти',action:()=>transitionTo(4)},{label:'Остаться и продолжить возвращать энергию',secondary:true,action:closeModal}]);return}if(!canPassPortal())return;showModal('Портал','Вы готовы перейти на следующий уровень?',`<p>Круг завершен, условия перехода выполнены. Следующий уровень: «${escapeHtml(next.name)}».</p><p>Вы можете остаться и продолжить исследование.</p>`,[{label:`Перейти на Уровень ${game.level+2}`,action:()=>transitionTo(game.level+1)},{label:'Остаться и продолжить исследование',secondary:true,action:closeModal}])}
function showTrueNeed(){showModal('Уровень 2','Моя истинная потребность',`<p><b>Ваш запрос:</b> ${escapeHtml(currentRequest())}</p><p><b>Осознание первого уровня:</b> ${escapeHtml(game.finalInsight)}</p><p><b>Принятые карты Потребностей:</b> ${escapeHtml(game.acceptedCards.filter(c=>c.deck==='Потребности').map(c=>c.title).join(', ')||'Пока нет')}</p><p><b>Телесные отметки:</b> ${escapeHtml(game.bodyMarks.map(m=>bodyLevels[m.level-1].name).join(', ')||'Пока нет')}</p><label for="modal-text">Что мне на самом деле нужно?</label><textarea id="modal-text" placeholder="Сформулируйте свою истинную потребность...">${escapeHtml(game.trueNeed)}</textarea>`,[{label:'Сохранить потребность',action:()=>{const value=ge('modal-text').value.trim();if(!value){announce('Запишите свою истинную потребность.');return}game.trueNeed=value;saveInsight('Моя истинная потребность',value);persist();closeModal()}},{label:'Позже',secondary:true,action:closeModal}])}
function showLevel2Key(){if(!game.trueNeed.trim()){showTrueNeed();return}showChoiceGuardian('Ключ Потребности')}
function showChoiceGuardian(source='Хранитель выбора'){showModal(source,'Мой выбор',`<p><b>Запрос:</b> ${escapeHtml(currentRequest())}</p><p><b>Первое осознание:</b> ${escapeHtml(game.finalInsight)}</p><p><b>Моя истинная потребность:</b> ${escapeHtml(game.trueNeed||'Пока не сформулирована')}</p><p><b>Исследованные потребности:</b> ${escapeHtml(game.acceptedCards.filter(c=>c.deck==='Потребности').map(c=>c.title).join(', ')||'Пока нет')}</p><div class="guardian-figure">${bodyFigure()}</div><p>Какую потребность вы признаете своей и готовы перестать игнорировать?</p><label for="modal-text">Что вы теперь выбираете для себя?</label><textarea id="modal-text">${escapeHtml(game.choice)}</textarea>`,[{label:'Я признаю эту потребность и считаю свой выбор точным',action:()=>{const value=ge('modal-text').value.trim();if(!game.trueNeed.trim()){announce('Сначала сформулируйте истинную потребность.');return}if(!game.bodyMarks.some(m=>m.gameLevel===1)){announce('Отметьте телесный отклик на потребность.');return}if(!value){announce('Запишите свой выбор.');return}game.choice=value;game.keys[1]=true;saveInsight(source,value);persist();showKey()}},{label:'Позже',secondary:true,action:closeModal}])}
function showNeedsMap(){showModal('Итог уровня','Моя карта потребностей',`<div class="awareness"><h3>Мой запрос</h3><p>${escapeHtml(currentRequest())}</p><h3>Первое осознание</h3><p>${escapeHtml(game.finalInsight)}</p><h3>Исследованные потребности</h3><p>${escapeHtml(game.acceptedCards.filter(c=>c.deck==='Потребности').map(c=>c.title).join(', ')||'Пока нет')}</p><h3>Моя истинная потребность</h3><p>${escapeHtml(game.trueNeed||'Пока не сформулирована')}</p><h3>Карта тела</h3>${bodyFigure()}<h3>Отметки на втором уровне</h3>${game.bodyMarks.filter(m=>m.gameLevel===1).map(m=>`<p>${escapeHtml(bodyLevels[m.level-1].name)}: ${escapeHtml([m.sensation,m.emotion,m.association,m.note].filter(Boolean).join(' · '))}</p>`).join('')||'<p>Пока нет</p>'}<h3>Мой выбор</h3><p>${escapeHtml(game.choice||'Пока не сформулирован')}</p><h3>Ключ</h3><p class="${game.keys[1]?'key-owned':'key-empty'}">⚿ ${game.keys[1]?'Ключ получен':'Пока не получен'}</p></div>`,[{label:'К карте тела',action:()=>showBodyMap()},{label:'Карта осознания I уровня',secondary:true,action:showAwareness},{label:'Продолжить',secondary:true,action:closeModal}]);ge('modal-content').querySelectorAll('.body-point').forEach(b=>b.addEventListener('click',()=>showBodyMap(null,Number(b.dataset.level))))}

const level3Shadows=()=>game.acceptedCards.filter(c=>c.deck==='Тень ↔ Сила'&&c.level===2);
const level3Support=()=>game.acceptedCards.filter(c=>c.deck==='Богини / Архетипы силы'&&c.level===2);
const shadowPair=c=>{const card=(cardManifest['Тень ↔ Сила']||[]).find(v=>v.id===c.id);return card?{shadow:card.title,power:card.fields.find(f=>f.label==='Скрытая Сила')?.text||''}:{shadow:c.title,power:''}};
const shadowPairs=()=>level3Shadows().map(shadowPair);
const pairsHtml=()=>shadowPairs().map(p=>`<p><b>${escapeHtml(p.shadow)}</b> → ${escapeHtml(p.power)}</p>`).join('')||'<p>Карты Тени пока не исследованы.</p>';
const level3Marks=()=>game.bodyMarks.filter(m=>m.gameLevel===2);
const marksHtml=()=>level3Marks().map(m=>`<p><b>${escapeHtml(bodyLevels[m.level-1]?.name||'Область тела')}:</b> ${escapeHtml([m.sensation,m.emotion,m.association,m.note].filter(Boolean).join(' · ')||'Отметка')}</p>`).join('')||'<p>Пока нет отметок третьего уровня.</p>';
function hasReflectionText(value){return [...value.trim()].filter(character=>!/\s/u.test(character)).length>=2}
function showShadowReflection(card){const pair=shadowDescriptions[card.id],event=game.pendingReflection;if(!pair||!event||event.cardId!==card.id){announce('Описание карты недоступно.');return}const paragraphs=list=>list.map(p=>`<p>${escapeHtml(p)}</p>`).join('');showModal('Карта «Тень ↔ Сила»',`Вам выпала карта «${pair.shadow}»`,`<div class="book-description"><h3>Тень: ${escapeHtml(pair.shadow)}</h3>${paragraphs(pair.shadowDescription)}<h3>Сила: ${escapeHtml(pair.power)}</h3>${paragraphs(pair.powerDescription)}</div><p class="reflection-reward">Запиши свое осознание и получи <b>+2 ⚡ энергии</b>.</p><label for="modal-text">Запиши свое осознание</label><textarea id="modal-text" placeholder="Что я заметила и какую Силу могу использовать осознанно?"></textarea>`,[{label:'Сохранить осознание и получить +2 ⚡',action:()=>{const text=ge('modal-text').value.trim();if(!hasReflectionText(text)){announce('Запиши хотя бы два непробельных символа.');return}if(game.insights.some(i=>i.eventId===event.eventId&&i.rewardClaimed)){announce('Энергия за эту карту уже получена.');return}game.insights.push({kind:'Тень ↔ Сила',level:2,cell:game.position,cardId:card.id,shadow:pair.shadow,power:pair.power,text,reward:2,rewardClaimed:true,eventId:event.eventId,at:new Date().toISOString()});earnEnergy(2,'Осознание Тень ↔ Сила');if(typeof awardShadowCrystal==='function')awardShadowCrystal(event.eventId);game.pendingReflection=null;persist();renderGame();ge('modal-content').innerHTML='<div class="reward-burst">+2 ⚡</div><p>Энергия возвращается к тебе</p>';ge('modal-buttons').replaceChildren();const btn=document.createElement('button');btn.textContent='Продолжить игру';btn.addEventListener('click',closeModal);ge('modal-buttons').append(btn)}}]);const field=ge('modal-text'),button=ge('modal-buttons').querySelector('button');const updateButton=()=>button.disabled=!hasReflectionText(field.value);field.addEventListener('input',updateButton);updateButton()}
function showAcceptance(){showModal('Уровень 3','Я принимаю свою Силу',`<p><b>Первоначальный запрос:</b> ${escapeHtml(currentRequest())}</p><p><b>Первое осознание:</b> ${escapeHtml(game.finalInsight)}</p><p><b>Истинная потребность:</b> ${escapeHtml(game.trueNeed)}</p><h3>Исследованные Тени и их Силы</h3>${pairsHtml()}<h3>Телесные отметки этого уровня</h3>${marksHtml()}<p>Что я готова признать и принять в себе? Какую Силу вижу за своей Тенью? Принятие не обязывает действовать из Тени.</p><label for="modal-text">Мое осознание</label><textarea id="modal-text">${escapeHtml(game.acceptanceInsight)}</textarea>`,[{label:'Сохранить осознание',action:()=>{const value=ge('modal-text').value.trim();if(!value){announce('Запишите осознание.');return}game.acceptanceInsight=value;saveInsight('Я принимаю свою Силу',value);persist();closeModal()}},{label:'Карта тела',secondary:true,action:()=>showBodyMap()},{label:'Позже',secondary:true,action:closeModal}])}
function showLevel3Guardian(source){showModal(source,'Какую часть себя я больше не хочу отрицать?',`<p><b>Мой запрос:</b> ${escapeHtml(currentRequest())}</p><p><b>Моя истинная потребность:</b> ${escapeHtml(game.trueNeed)}</p><h3>Тени и Силы</h3>${pairsHtml()}<h3>Карта тела</h3>${marksHtml()}<p><b>Мои осознания:</b> ${escapeHtml(game.insights.filter(i=>i.level===2).map(i=>i.text).join('; ')||'Пока нет')}</p><label for="main-shadow">Какую часть себя я больше не хочу отрицать?</label><input id="main-shadow" type="text" value="${escapeHtml(game.mainShadow)}"><label for="accepted-power">Какую Силу я готова признать своей?</label><input id="accepted-power" type="text" value="${escapeHtml(game.acceptedPower)}"><label for="modal-text">Мое главное осознание...</label><textarea id="modal-text">${escapeHtml(game.guardianInsight)}</textarea>`,[{label:'Я признаю эту часть себя и принимаю ее Силу',action:()=>{const shadow=ge('main-shadow').value.trim(),power=ge('accepted-power').value.trim(),insight=ge('modal-text').value.trim();if(!level3Shadows().length){announce('Сначала исследуйте карту Тень ↔ Сила.');return}if(!shadow||!power||!insight){announce('Заполните тему Тени, Силу и главное осознание.');return}game.mainShadow=shadow;game.acceptedPower=power;game.guardianInsight=insight;game.keys[2]=true;saveInsight(source,insight);persist();showKey()}},{label:'Позже',secondary:true,action:closeModal}])}
function showAcceptanceMap(){showModal('Итог уровня','Моя карта принятия',`<div class="awareness"><h3>Первоначальный запрос</h3><p>${escapeHtml(currentRequest())}</p><h3>Осознание первого уровня</h3><p>${escapeHtml(game.finalInsight)}</p><h3>Истинная потребность</h3><p>${escapeHtml(game.trueNeed)}</p><h3>Исследованные Тени → Силы</h3>${pairsHtml()}<h3>Главная Тень / тема</h3><p>${escapeHtml(game.mainShadow||'Пока не определена')}</p><h3>Сила, которую я принимаю</h3><p>${escapeHtml(game.acceptedPower||'Пока не определена')}</p><h3>Карта тела · уровень 3</h3>${bodyFigure()}${marksHtml()}<h3>Поддержка</h3><p>${escapeHtml(level3Support().map(c=>c.title).join(', ')||'Пока не получена')}</p><h3>Главное осознание</h3><p>${escapeHtml(game.guardianInsight||game.acceptanceInsight||'Пока не записано')}</p><h3>Ключ Принятия</h3><p class="${game.keys[2]?'key-owned':'key-empty'}">⚿ ${game.keys[2]?'Получен':'Пока не получен'}</p></div>`,[{label:'К карте тела',action:()=>showBodyMap()},{label:'Продолжить',secondary:true,action:closeModal}]);ge('modal-content').querySelectorAll('.body-point').forEach(b=>b.addEventListener('click',()=>showBodyMap(null,Number(b.dataset.level))))}

function showKeyCondition(){if(!game.bodyMarks.length){showModal('Ключ Ясности','Отметьте телесный отклик','<p>Для завершения исследования сначала отметьте место отклика на Карте тела.</p>',[{label:'Открыть Карту тела',action:()=>showBodyMap()},{label:'Позже',secondary:true,action:closeModal}]);return}showFinalInsight('Ключ Ясности')}
function showFinalInsight(source){const summary=`<p><b>Ваш запрос:</b> ${escapeHtml(currentRequest())}</p><p><b>Что вы заметили:</b> ${escapeHtml(game.acceptedCards.map(c=>c.title).join(', ')||'Карты еще не приняты')}</p><p><b>Отмеченные уровни:</b> ${escapeHtml([...new Set(game.bodyMarks.map(m=>m.level))].map(i=>bodyLevels[i-1].name).join(', ')||'Нет отметок')}</p><p><b>Сохраненные осознания:</b> ${escapeHtml(game.insights.map(i=>i.text).join('; ')||'Пока нет')}</p><div class="guardian-figure">${bodyFigure()}</div>`;showModal(source,'Главное осознание',`${summary}<label for="modal-text">Какое главное осознание вы получили о своем запросе?</label><textarea id="modal-text">${escapeHtml(game.finalInsight)}</textarea>`,[{label:'Я считаю это осознание точным и чувствую отклик',action:()=>{const value=ge('modal-text').value.trim();if(!value){announce('Запишите главное осознание.');return}if(!game.bodyMarks.length){announce('Сначала отметьте телесный отклик.');return}saveInsight(source,value);game.finalInsight=value;game.keys[0]=true;persist();showKey()}},{label:'Вернуться позже',secondary:true,action:closeModal}])}
const bodyLevels=[
 {name:'Муладхара',location:'Основание тела / область промежности',shade:'Красная',caption:'Безопасность и опора',topics:'Безопасность, тело, материальная устойчивость, дом, базовые потребности, деньги как ресурс безопасности, страх потери, ощущение опоры.',y:46,color:'#ef3058'},
 {name:'Свадхистхана',location:'Ниже пупка',shade:'Оранжевая',caption:'Желания, чувства и удовольствие',topics:'Желания, удовольствие, эмоции, чувственность, творчество, контакт с потребностями и близостью.',y:38,color:'#f87932'},
 {name:'Манипура',location:'Солнечное сплетение / выше пупка',shade:'Желтая',caption:'Личность, сила и социум',topics:'Самооценка, уверенность, достижения, личная сила, границы, действия и проявленность.',y:30,color:'#ffc23e'},
 {name:'Анахата',location:'Центр груди / область сердца',shade:'Зеленая',caption:'Любовь и отношения',topics:'Любовь, отношения, принятие, близость, доверие, связь с собой и другими.',y:22,color:'#67d66c'},
 {name:'Вишуддха',location:'Область горла',shade:'Голубая',caption:'Голос и самовыражение',topics:'Голос, коммуникация, право говорить, самовыражение, выражение потребностей и честность.',y:14,color:'#48d9da'},
 {name:'Аджна',location:'Центр лба',shade:'Синяя / индиго',caption:'Видение и понимание',topics:'Понимание, видение ситуации, убеждения, восприятие, взаимосвязи и внутреннее направление.',y:7,color:'#315be6'},
 {name:'Сахасрара',location:'Над макушкой',shade:'Фиолетово-белая',caption:'Смысл и направление',topics:'Смысл, ценности, предназначение, мировоззрение и направление жизни.',y:1,color:'#d7b5ff'}
];
function bodyFigure(){return `<div class="body-figure"><img src="./body-figure.png" alt="Стилизованная фигура человека для символической карты тела">${bodyLevels.map((l,i)=>`<button class="body-point" type="button" data-level="${i+1}" style="--point-color:${l.color};top:${l.y}%" aria-label="${l.name}, ${l.caption}" title="${l.name}">${game.bodyMarks.filter(m=>m.level===i+1).length||'✦'}</button>`).join('')}</div>`}
function showBodyMap(card=null,selected=null,draft={}){const cardLevel=card?.bodyLevel||card?.symbolicLevel||null,chosen=selected||null,info=chosen?bodyLevels[chosen-1]:null;const field=(id,label,placeholder='')=>`<label for="${id}">${label}</label><input id="${id}" type="text" value="${escapeHtml(draft[id]||'')}" placeholder="${placeholder}">`;const content=`<p>Где в теле вы чувствуете отклик на эту тему? Выберите область сами. ${cardLevel?`Уровень карты: ${escapeHtml(bodyLevels[cardLevel-1].name)}. Он подсвечен отдельно.`:''}</p><div class="body-map">${bodyFigure()}<div class="body-options">${bodyLevels.map((l,i)=>`<button type="button" class="body-option ${chosen===i+1?'selected':''}" data-level="${i+1}" style="--point-color:${l.color}">${i+1}. ${l.name}<small>${l.shade} · ${l.location}<br><b>${l.caption}</b></small></button>`).join('')}</div></div><div class="body-description">${info?`<strong>${info.name} — ${info.caption}</strong><p>${info.topics}</p>`:'<p>Нажмите на светящуюся точку или название уровня.</p>'}</div>${field('sensation','Что я чувствую?','Напряжение, тепло, тяжесть...')}${field('emotion','Какая эмоция возникает?')}${field('color','Какого это цвета?')}${field('size','Какого размера ощущение?','Маленькое, среднее, большое...')}${field('association','С чем для меня это связано?')}<label for="body-note">Мое осознание (необязательно)</label><textarea id="body-note">${escapeHtml(draft.note||'')}</textarea><p class="modal-note">Символическая модель игры, не медицинская диагностика.</p>`;showModal('Тело','Карта тела',content,[{label:'Сохранить отметку',action:()=>{if(!chosen){announce('Выберите область на карте тела.');return}const values=readBodyDraft();game.bodyMarks.push({requestAtTime:currentRequest(),level:chosen,cardId:card?.id||null,cardTitle:card?.title||null,eventId:card?game.openedCards.at(-1)?.eventId||null:null,cardLevel,gameLevel:game.level,...values,at:new Date().toISOString()});persist();closeModal()}},{label:'Карта осознания',secondary:true,action:showAwareness}]);ge('modal-content').querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>showBodyMap(card,Number(b.dataset.level),readBodyDraft())));ge('modal-content').querySelectorAll('.body-point').forEach(b=>b.classList.toggle('suggested',Number(b.dataset.level)===cardLevel));ge('modal-content').querySelectorAll('.body-point').forEach(b=>b.classList.toggle('selected',Number(b.dataset.level)===chosen))}
function readBodyDraft(){return {sensation:ge('sensation').value.trim(),emotion:ge('emotion').value.trim(),color:ge('color').value.trim(),size:ge('size').value.trim(),association:ge('association').value.trim(),note:ge('body-note').value.trim()}}

function showAwareness(){const marks=[...new Set(game.bodyMarks.map(m=>m.level))];showModal('Итог уровня','Моя карта осознания',`<div class="awareness"><h3>Мой запрос</h3><p>${escapeHtml(currentRequest()||'Еще не записан')}</p><h3>Что я увидела</h3>${game.insights.length?game.insights.map(i=>`<p>${escapeHtml(i.text)}</p>`).join(''):'<p>Записи появятся по ходу игры.</p>'}<h3>Карта тела</h3>${bodyFigure()}<h3>Мои уровни</h3><p>${marks.map(i=>`${escapeHtml(bodyLevels[i-1].name)} — ${escapeHtml(bodyLevels[i-1].caption)} (${game.bodyMarks.filter(m=>m.level===i).length})`).join('<br>')||'Отметок пока нет'}</p><h3>Наблюдения о теле</h3>${game.bodyMarks.map(m=>`<p><b>${escapeHtml(bodyLevels[m.level-1].name)}:</b> ${escapeHtml([m.sensation,m.emotion,m.color,m.size,m.association,m.note].filter(Boolean).join(' · ')||'Отмечен телесный отклик')}</p>`).join('')}<h3>Главное осознание</h3><p>${escapeHtml(game.finalInsight||'Появится после встречи с Хранителем Правды')}</p><h3>Ключ</h3><p class="${game.keys[0]?'key-owned':'key-empty'}">⚿ ${game.keys[0]?'Ключ Ясности получен':'Пока не получен'}</p></div>`,[{label:'К карте тела',action:()=>showBodyMap()},{label:'Продолжить игру',secondary:true,action:closeModal}]);ge('modal-content').querySelectorAll('.body-point').forEach(b=>b.addEventListener('click',()=>showBodyMap(null,Number(b.dataset.level))))}
const diceFaces=['⚀','⚁','⚂','⚃','⚄','⚅'];
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function rollDice(){if(moving||game.pendingMovement||game.pendingCardCompletion||modalOpen||!game.originalRequest.trim()||game.stage!=='board'||game.level>4)return;if(game.skipTurns>0){game.skipTurns--;game.turn++;persist();announce('Ход пропущен по карте события.');return}game.portalReached=false;moving=true;renderGame();ge('dice-face').classList.add('rolling');const roll=1+Math.floor(Math.random()*6);await delay(450);ge('dice-face').classList.remove('rolling');ge('dice-face').textContent=diceFaces[roll-1];moving=false;game.pendingRoll={roll,turn:game.turn};persist();await moveSteps(roll);completeDiceTurn()}

ge('roll-button').addEventListener('click',rollDice);
ge('start-request').addEventListener('input',()=>ge('start-game').disabled=!ge('start-request').value.trim());ge('start-game').addEventListener('click',()=>{const value=ge('start-request').value.trim();if(!value)return;game.originalRequest=value;game.request=value;game.stage='intro';persist();renderGame()});ge('begin-research').addEventListener('click',()=>{if(!game.originalRequest.trim())return;game.stage='board';persist();renderGame()});ge('begin-level2').addEventListener('click',()=>{if(!game.originalRequest.trim())return;game.stage='board';persist();renderGame()});ge('begin-level3').addEventListener('click',()=>{if(!game.originalRequest.trim())return;game.stage='board';persist();renderGame()});ge('begin-level5').addEventListener('click',()=>{if(!game.originalRequest.trim())return;game.stage='board';persist();renderGame()});ge('spheres-button').addEventListener('click',showSphereTablet);ge('center-spheres').addEventListener('click',showSphereTablet);ge('body-button').addEventListener('click',()=>showBodyMap());ge('awareness-button').addEventListener('click',()=>game.level===4?showCreationMap():game.level===3?showReturnMap():game.level===2?showAcceptanceMap():game.level===1?showNeedsMap():showAwareness());
ge('request-button').addEventListener('click',()=>showModal('Личный запрос','Мой запрос',`<label for="modal-text">С чем я пришла в игру?</label><textarea id="modal-text" placeholder="Я хочу..., но сейчас...">${escapeHtml(game.request)}</textarea>`,[{label:'Сохранить',action:()=>{updateCurrentRequest(ge('modal-text').value,'Мой запрос');closeModal()}},{label:'Отмена',secondary:true,action:closeModal}]));
ge('journal-button').addEventListener('click',()=>{const content=game.insights.length?game.insights.map((i,n)=>`<div class="journal-entry"><small>${n+1}. ${escapeHtml(i.kind)} · ${escapeHtml(levels[i.level]?.name||'Уровень')}${i.shadow?` · ${escapeHtml(i.shadow)} → ${escapeHtml(i.power)} · +${i.reward} ⚡ · ${escapeHtml(i.at)}`:''}</small><p>${escapeHtml(i.text)}</p></div>`).join(''):'<p>Пока записей нет. Клетка Осознания и Хранитель Правды сохраняют ваши ответы здесь.</p>';showModal('Мой путь','Журнал осознаний',content,singleClose())});
ge('rules-button').addEventListener('click',()=>{if(game.level===4){showModal('Правила пятого уровня','Я создаю','<h3>Куда я направляю свою энергию?</h3><p>Выбирайте сферу, формулируйте цель и подтверждайте, сколько доступной энергии направить в нее. Откройте «Сферы жизни», чтобы увидеть распределение и добавить несколько целей. Карты «Творение», действия и осознания помогают перевести ресурс в реальные шаги.</p><p>На круге 20 клеток и Портал в Центр. Ключ Воплощения находится на клетке №6. За полный круг вы получаете +1 💎. Содержание Центра появится после утверждения следующего этапа.</p>',singleClose());return}if(game.level===3){showModal('Правила четвертого уровня','Я возвращаю','<h3>Цель</h3><p>Возвращайте свое внимание и накапливайте энергию для созидания. Исследуйте карты «Возвращение энергии», записывайте осознания и получайте поддержку Архетипов силы.</p><p>На круге 20 клеток и Портал. Энергетические клетки дают +1 ⚡, полный круг дает +1 💎. Получите Ключ Энергии на клетке №6. Для перехода на уровень «Я создаю» нужен Ключ, полный круг и не менее 25 ⚡. Вы можете остаться и продолжить игру.</p>',singleClose());return}if(game.level===2){showModal('Правила третьего уровня','Я принимаю','<h3>Цель</h3><p>Исследовать то, что вы можете отрицать в себе, увидеть скрытую за Тенью энергию и определить Силу, которую готовы признать.</p><p>Замечайте реакцию на карты, желание их отвергнуть, эмоции и отклик тела. Принятие части своего опыта не обязывает проявлять любое поведение. Вы выбираете, как пользоваться найденной Силой.</p><p>На круге доступны колоды «Тень ↔ Сила», «Другой взгляд», «Особое событие» и «Богини / Архетипы силы» как Поддержка. За полный круг +1 💎. Для перехода исследуйте Тень, сформулируйте осознание и принимаемую Силу, получите Ключ и пройдите Портал.</p>',singleClose());return}if(game.level===1){showModal('Правила второго уровня','Я выбираю','<h3>Цель</h3><p>Исследовать, какая потребность находится за первоначальным запросом, и сформулировать свою истинную потребность.</p><p>Бросайте кубик, выполняйте действие клетки, исследуйте карты «Потребности», при необходимости выбирайте другую. Отмечайте отклик на Карте тела, записывайте осознания и сформулируйте потребность. После полного круга выберите: принять +1 ⚡ или отказаться. Награда Кристаллом учитывается отдельно. Ключ можно получить на его клетке или у Хранителя выбора после формулировки потребности, телесной отметки и выбора.</p><p>С исходным запросом, первым осознанием и накопленной энергией вы продолжаете ту же игру.</p><p class=modal-note>20 определенных клеток и Портал; порядок следует присланному списку.</p>',singleClose());return}const descriptions={portal:['◇','Завершает круг и предлагает принять +1 ⚡. Кристаллы учитываются отдельно. Переход при выполнении условий.'],event:['✦','Карта совместимого Особого события; однозначные эффекты выполняются автоматически.'],energy:['⚡','Получите 1 энергию.'],resource:['✧','Ресурсная практика этапа.'],diagnostic:['▣','Карта «Диагностика» и возможность отметить телесный отклик.'],ocean:['≈','Уточните свой запрос.'],insight:['✧','Запишите осознание.'],key:['⚿','Сформулируйте главное осознание и получите Ключ после телесной отметки.'],guardian:['✦','Сформулируйте главное осознание и получите Ключ.'],view:['◉','Карта «Другой взгляд».']};const used=[...new Set(routeCells().map(c=>c.type))];const list=used.map(type=>`<li>${descriptions[type][0]} <b>${escapeHtml(routeCells().find(c=>c.type===type).name)}</b> — ${descriptions[type][1]}</li>`).join('');showModal('Правила первого уровня','Я осознаю',`<h3>Цель уровня</h3><p>Исследовать свой запрос, понять связанные с ним эмоции и телесные реакции и сформировать более точное осознание происходящего.</p><h3>Почему мы обращаем внимание на тело?</h3><p>В авторской системе игры «Точка силы» тело рассматривается как важный источник информации о внутреннем состоянии человека. Мы можем не сразу осознавать свои эмоции, напряжение или внутренний конфликт, но замечать их через телесные ощущения. Поэтому на первом уровне мы исследуем не только мысли о запросе, но и то, как он ощущается в теле.</p><h3>На что обращать внимание</h3><p>Мысли, эмоции, место отклика, цвет и размер ощущения, его изменения, связь со сферой жизни и осознания от карт.</p><h3>Как играть</h3><ol><li>Сформулируйте запрос и отметьте телесный отклик.</li><li>Бросайте кубик и выполняйте действие клетки.</li><li>Исследуйте карты и записывайте осознания.</li><li>Возвращайтесь к Карте тела и уточняйте наблюдения.</li><li>После полного круга выберите: принять +1 ⚡ или отказаться. Награда Кристаллом учитывается отдельно.</li><li>Сформулируйте главное осознание, получите Ключ и пройдите через Портал.</li></ol><h3>Клетки этого уровня</h3><ul>${list}</ul><p class="modal-note">19 игровых клеток и Портал. Карта тела является символической моделью, не медицинской диагностикой.</p>`,singleClose())});

ge('future-overview').addEventListener('click',()=>{document.querySelector('#tab-explore').click();selected=game.level;renderRoute();renderLevel()});
function confirmNewSession(){showModal('Новая тестовая партия','Начать заново?','<p>Текущие записи и прогресс этого браузера будут удалены.</p>',[{label:'Начать заново',action:()=>{game=defaultGame();ge('start-request').value='';ge('start-game').disabled=true;persist();closeModal();renderGame()}},{label:'Отмена',secondary:true,action:closeModal}])}
ge('new-session').addEventListener('click',confirmNewSession);ge('reset-button').addEventListener('click',confirmNewSession);
ge('sound-toggle').textContent=soundEnabled?'🔊 Звук':'🔇 Звук';ge('sound-toggle').addEventListener('click',()=>{soundEnabled=!soundEnabled;localStorage.setItem('tochka-sily-sound',soundEnabled?'on':'off');ge('sound-toggle').textContent=soundEnabled?'🔊 Звук':'🔇 Звук'});Promise.all([fetch('./cards.json').then(r=>{if(!r.ok)throw Error('cards');return r.json()}),fetch('./shadow-descriptions.json').then(r=>{if(!r.ok)throw Error('book');return r.json()}),fetch('./card-images.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]).then(([cards,book,images])=>{cardManifest=cards;for(const deck of Object.values(cardManifest))for(const card of deck)card.image=images[card.id]||card.image||null;shadowDescriptions=Object.fromEntries(book.map(pair=>[pair.id,pair]));if(game.pendingReflection){const card=cardManifest['Тень ↔ Сила']?.find(c=>c.id===game.pendingReflection.cardId);if(card)showShadowReflection(card)}}).catch(()=>announce('Не удалось загрузить колоды или книгу описаний.'));
makeBoard();renderGame();

function earnEnergy(amount,source){globalThis.SoundManager?.play('energyGain',{fast:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches});game.energy+=amount;game.energyHistory.push({kind:'earned',level:game.level,amount,source,at:new Date().toISOString()});if(typeof energyFlight==='function')energyFlight(amount)}

function completeDiceTurn(){const pending=game.pendingRoll;if(!pending)return;game.turn=pending.turn+1;game.lastRoll=pending.roll;game.pendingRoll=null;persist();renderGame();handleCell();if(pendingPortal&&!modalOpen){pendingPortal=false;showPortalChoice()}else if(game.position===0&&!canPassPortal())announce('Круг завершен. Проверь условия перехода.') }
